script:
-- realistic: comments, GO batches, a view, a trigger, a procedure with TRY/CATCH
CREATE TABLE dbo.orders (
    id INT IDENTITY(1,1) PRIMARY KEY,
    status VARCHAR(10) NOT NULL DEFAULT 'new',
    amount DECIMAL(10,2) NOT NULL CHECK (amount >= 0)
);
CREATE INDEX ix_orders_status ON dbo.orders (status);
GO

/* the audit table: the trigger below fills it */
CREATE TABLE dbo.orders_audit (order_id INT, note VARCHAR(50));
GO

CREATE VIEW dbo.open_orders AS
SELECT id, amount FROM dbo.orders WHERE status = 'new';
GO

CREATE TRIGGER dbo.trg_orders_audit ON dbo.orders AFTER INSERT AS
BEGIN
    INSERT INTO dbo.orders_audit (order_id, note) SELECT id, 'inserted; by trigger' FROM inserted;
END;
GO

CREATE PROCEDURE dbo.add_order @amount DECIMAL(10,2) AS
BEGIN
    BEGIN TRY
        BEGIN TRANSACTION;
        INSERT INTO dbo.orders (amount, status) VALUES (@amount, CASE WHEN @amount > 100 THEN 'review' ELSE 'new' END);
        COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
        THROW;
    END CATCH
END;
GO

EXEC dbo.add_order 50;
EXEC dbo.add_order 500;
GO

